import * as React from "react"

function LinkedinLoginSignupButton({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="linkedin-login-signup-button"
      className={className}
      {...props}
    >
      <button
          className="px-4 py-2 border flex gap-2 border-slate-200 rounded-lg text-slate-700 hover:border-slate-400 hover:text-slate-900 hover:shadow transition duration-150">
          <img className="w-6 h-6" src="https://www.svgrepo.com/show/475661/linkedin-color.svg" loading="lazy" alt="google logo" />
          <span className="pt-0.5">Login with Linkedin</span>
      </button>
    </div>
  )
}

export { LinkedinLoginSignupButton }
